<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$user=requireUser($pdo);
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$pdo->prepare('SELECT p.id,p.slug,p.title,p.excerpt,p.content,p.status,p.created_at,c.name category_name FROM posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.user_id=? ORDER BY p.created_at DESC');$q->execute([$user['id']]);$posts=$q->fetchAll();foreach($posts as &$post)$post['content']=sanitizeRichText((string)$post['content']);unset($post);exit(json_encode(['user'=>$user,'posts'=>$posts]));}
if($_SERVER['REQUEST_METHOD']==='POST'){$d=input();$avatar=mb_substr(trim($d['avatar_url']??''),0,500);if($avatar!==''&&!isApiUploadUrl($avatar,$config)){http_response_code(422);exit(json_encode(['error'=>'Invalid profile image.']));}$q=$pdo->prepare('UPDATE users SET avatar_url=? WHERE id=?');$q->execute([$avatar,$user['id']]);exit(json_encode(['ok'=>true,'avatar_url'=>$avatar]));}
if($_SERVER['REQUEST_METHOD']==='PUT'){$d=input();$name=trim($d['name']??'');if(strlen($name)<2){http_response_code(422);exit(json_encode(['error'=>'Name is required.']));}$bio=mb_substr(trim($d['bio']??''),0,500);$website=mb_substr(trim($d['website']??''),0,255);$avatar=mb_substr(trim($d['avatar_url']??$user['avatar_url']??''),0,500);$profession=mb_substr(trim($d['profession']??''),0,120);$address=mb_substr(trim($d['address']??''),0,255);$interests=mb_substr(trim($d['interests']??''),0,500);if($website!==''&&!filter_var($website,FILTER_VALIDATE_URL)){http_response_code(422);exit(json_encode(['error'=>'Enter a complete website URL, including https://.']));}if($avatar!==''&&!isApiUploadUrl($avatar,$config)){http_response_code(422);exit(json_encode(['error'=>'Invalid profile image.']));}$q=$pdo->prepare('UPDATE users SET name=?,bio=?,website=?,avatar_url=?,profession=?,address=?,interests=? WHERE id=?');$q->execute([$name,$bio,$website,$avatar,$profession,$address,$interests,$user['id']]);exit(json_encode(['ok'=>true,'avatar_url'=>$avatar]));}
http_response_code(405);echo json_encode(['error'=>'Method not allowed.']);
function isApiUploadUrl(string $url,array $config):bool{$base=rtrim((string)($config['api_url']??''),'/');return $base!==''&&preg_match('#^'.preg_quote($base,'#').'/uploads/[a-zA-Z0-9._-]+$#',$url)===1;}
